'use strict';
let app, project, page='brief', dirty=false, areaIndex=0, roomIndex=0, npcIndex=0, questIndex=0, templateIndex=0, report=null, proposal=null, previousDraft=null, generating=false;
const $=s=>document.querySelector(s);
const clone=o=>JSON.parse(JSON.stringify(o));
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const E=escapeHtml;
async function api(path,body){const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Studio-Token':app.csrf},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j;}
let timer;function notify(message,error=false){$('#toast').textContent=message;$('#toast').className=error?'error':'';$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,error?18000:6000);}
async function task(button,fn){const label=button?.textContent;if(button){button.disabled=true;button.textContent='Working…';}try{await fn();}catch(e){notify(e.message,true);}finally{if(button){button.disabled=false;button.textContent=label;}}}
function value(path){return path.split('.').reduce((o,k)=>o[k],project);}
function field(label,path,type='text',options=[]){const v=value(path);let html;
 if(type==='textarea')html=`<textarea data-field="${path}">${E(v)}</textarea>`;
 else if(type==='select')html=`<select data-field="${path}">${options.map(o=>{const [id,name]=Array.isArray(o)?o:[o,o];return `<option value="${E(id)}" ${String(v)===String(id)?'selected':''}>${E(name)}</option>`;}).join('')}</select>`;
 else if(type==='checkbox')return `<label class="check"><input type="checkbox" data-field="${path}" ${v?'checked':''}>${E(label)}</label>`;
 else html=`<input data-field="${path}" type="${type}" value="${E(v)}" ${type==='number'?'step="1"':''}>`;
 return `<label class="field"><span>${E(label)}</span>${html}</label>`;
}
function change(){dirty=true;report=null;$('#saveState').textContent='Unsaved draft';}
function roomOptions(){return project.areas.flatMap(a=>a.rooms.map(r=>[r.id,a.name+' / '+r.name]));}
function questOptions(empty='Always available'){return [['',empty],...project.quests.map(q=>[q.id,q.name])];}
function questSummary(q){const names=Object.fromEntries(q.steps.map(s=>[s.id,s.name]));const next=id=>E(id?(names[id]||id):'Complete');return q.steps.map(s=>E(s.name)+' → '+(s.kind==='choice'?s.choices.map(c=>E(c.label)+': '+next(c.next)).join(' / '):next(s.next))).join('<br>');}
function npcOptions(empty='Start automatically'){return [['',empty],...project.npcs.map(n=>[n.id,n.name])];}
function id(prefix){let i=1;const raw=JSON.stringify(project);while(raw.includes('"'+prefix+i+'"'))i++;return prefix+i;}
function area(){return project.areas[areaIndex];}
function selectedRoom(){return area()?.rooms[roomIndex];}
function meta(){return {areas:project.areas.length,rooms:project.areas.reduce((n,a)=>n+a.rooms.length,0),characters:project.npcs.length,encounters:project.encounters.length,quests:project.quests.length};}
function renderHeader(){if(!project)return;$('#projectTitle').textContent=project.title;$('#saveState').textContent=dirty?'Unsaved draft':'Saved';$('#stats').innerHTML=Object.entries(meta()).map(([k,n])=>`<div class="stat"><strong>${n}</strong><span>${k}</span></div>`).join('');document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',page===b.dataset.page));}
function projectList(){const current=project?.id;$('#projectSelect').innerHTML=app.projects.filter(p=>p.schema_version===2).map(p=>`<option value="${E(p.id)}">${E(p.title)}</option>`).join('');if(current)$('#projectSelect').value=current;}
async function load(ident){project=(await api('/api/project?id='+encodeURIComponent(ident))).project;if(project.schema_version!==2)throw Error('This is a legacy companion project. Use the original companion page for that file.');dirty=false;report=null;areaIndex=roomIndex=npcIndex=questIndex=templateIndex=0;render();}
async function save(){project=(await api('/api/project/save',{project})).project;dirty=false;app.projects=(await api('/api/state')).projects;projectList();renderHeader();notify('Adventure project saved.');}
function assistant(defaultScope){return `<aside class="author-aside"><div class="card accent"><div class="card-head"><h3>AI DM · Adventure design</h3><span class="badge">Authoring</span></div><p class="muted">Turn your storyline and design notes into playable content. Every generated proposal is editable.</p><label class="field"><span>What should the AI create?</span><select id="aiScope">${[['adventure','Complete adventure'],['story','Story and ending prose'],['areas','Areas, rooms and connections'],['cast','Characters and dialogue'],['companions','Companions and starting templates'],['behaviors','Patrols and NPC social behavior'],['encounters','Encounters, items and furnishings'],['quests','Quests and supporting cast'],['populate','Populate the selected area']].map(([v,t])=>`<option value="${v}" ${v===defaultScope?'selected':''}>${t}</option>`).join('')}</select></label><label class="field"><span>Your direction</span><textarea id="aiDirection" placeholder="Use my storyline. Give each room a purpose, add characters with different motives, and create quests that lead to a complete ending."></textarea></label><button data-action="generate" class="primary" ${generating?'disabled':''}>Generate proposal</button><p class="hint">The AI uses your story, room plans, character notes and encounter briefs. It creates native game content for export.</p>${previousDraft?'<button data-action="undoAI" class="quiet">Undo last applied proposal</button>':''}</div><div class="note">Generation happens while authoring. The exported adventure includes its story, conversations and quest logic and can be played without this editor.</div></aside>`;}
function brief(){return `<div class="hero"><span class="badge">Build a complete adventure</span><h2 class="after-card">From your storyline to their next game.</h2><p>Describe the world, define its spaces and characters, then let the AI DM build quests and encounters around them. Review the result and export a module players can run locally and share.</p><div class="flow"><span>Storyline</span><b>→</b><span>Areas & rooms</span><b>→</b><span>Characters & quests</span><b>→</b><span>Playable .mod</span></div></div><div class="author-grid"><div><div class="card">${field('Adventure title','title')}${field('Public premise','summary','textarea')}${field('Storyline · events, characters, twists, desired resolution','story','textarea')}${field('Tone and style','tone','textarea')}<div class="row three">${field('Minimum party level','level_min','number')}${field('Maximum party level','level_max','number')}${field('Intended party size','party_size','number')}</div></div><div class="card"><h3>The player’s journey</h3>${field('Opening narration','opening','textarea')}${field('Ending narration','ending','textarea')}${field('Starting room','start_room','select',roomOptions())}<p class="hint">Quest choices can have their own outcome text and different final objectives. The ending narration appears when every main quest is complete.</p></div></div>${assistant('adventure')}</div>`;}
function worldMap(a){const layout=report?.layouts?.[a.id];const w=a.width,h=a.height;const roomMap=Object.fromEntries(a.rooms.map(r=>[r.id,r]));
 const port=(r,s)=>({north:[r.x+r.width/2,r.y+r.height-.2],south:[r.x+r.width/2,r.y+.2],east:[r.x+r.width-.2,r.y+r.height/2],west:[r.x+.2,r.y+r.height/2]}[s]);
 let exits='';project.connections.forEach(c=>{for(const [rid,side,dest] of [[c.from_room,c.from_side,c.to_room],[c.to_room,c.to_side,c.from_room]]){const r=roomMap[rid];if(!r)continue;const [x,y]=port(r,side);exits+=`<circle class="exit" cx="${x}" cy="${h-y}" r=".22"><title>${E(c.name)}: ${side} to ${E(dest)}</title></circle>`;}});
 return `<svg class="worldmap" viewBox="0 0 ${w} ${h}" role="img" aria-label="Room plan for ${E(a.name)}"><defs><pattern id="planGrid" width="1" height="1" patternUnits="userSpaceOnUse"><path class="mapgrid" d="M 1 0 L 0 0 0 1" fill="none"/></pattern></defs><rect width="${w}" height="${h}" fill="url(#planGrid)"/>${(layout?.corridors||[]).flatMap(c=>c.cells.map(([x,y])=>`<rect class="corridor" x="${x}" y="${h-y-1}" width="1" height="1"/>`)).join('')}${a.rooms.map((r,i)=>`<g><rect data-room-map="${i}" class="room ${i===roomIndex?'selected-room':''}" x="${r.x}" y="${h-r.y-r.height}" width="${r.width}" height="${r.height}" rx="${a.type==='cave'?.3:.08}"/><text class="room-label" textLength="${Math.min(r.width-.3,Math.min(r.name.length,26)*.23)}" lengthAdjust="spacingAndGlyphs" x="${r.x+r.width/2}" y="${h-r.y-r.height/2-.1}">${E(r.name.slice(0,26))}</text><text class="room-detail" x="${r.x+r.width/2}" y="${h-r.y-r.height/2+.55}">${r.width*10} × ${r.height*10} m</text></g>`).join('')}${exits}</svg>`;
}
function world(){if(!project.areas.length)return `<div class="card"><h2>Design the first area.</h2><button data-action="addArea" class="primary">Add area</button></div>`;areaIndex=Math.min(areaIndex,project.areas.length-1);roomIndex=Math.min(roomIndex,Math.max(0,area().rooms.length-1));const a=area(),ap='areas.'+areaIndex,r=selectedRoom(),rp=ap+'.rooms.'+roomIndex;
 return `<div class="section-head"><div><h2>Give the world its shape.</h2><p class="muted">Set the area type, size and appearance, then place rooms and connect their exits.</p></div><button data-action="addArea">＋ Add area</button></div><div class="tabs">${project.areas.map((a,i)=>`<button data-area="${i}" class="${i===areaIndex?'active':''}">${E(a.name)}</button>`).join('')}</div><div class="author-grid"><div><div class="card"><div class="row">${field('Area name',ap+'.name')}${field('Area type',ap+'.type','select',Object.entries(app.authoring_catalog.area_types))}</div>${field('How should this area look and feel? What belongs here?',ap+'.description','textarea')}<div class="row three">${field('Width · tiles (10 m each)',ap+'.width','number')}${field('Height · tiles (10 m each)',ap+'.height','number')}${field('Requested room count',ap+'.room_count','number')}</div>${field('Lighting',ap+'.lighting','select',['warm','cold','dark','daylight'])}<div class="actions"><button data-action="arrange">Generate room layout</button><button data-action="connectRooms">Connect these rooms</button><button data-action="preview">Preview / check connections</button></div><p class="hint">Layout generation respects the area size and requested room count. Connecting rooms creates editable corridors. Use exit connections between different areas.</p></div><div class="map-wrap">${worldMap(a)}<p class="hint">North is up. Each square is a 10 m tile. Gold dots are exit positions. Check connections to show the exact routed corridors used by the exporter.</p></div><div class="room-picker">${a.rooms.map((r,i)=>`<button data-room="${i}" class="${i===roomIndex?'active':''}">${E(r.name)}</button>`).join('')}<button data-action="addRoom">＋ Room</button></div>${r?`<div class="card"><div class="card-head"><h3>Room design</h3><button class="quiet danger" data-action="deleteRoom">Remove room</button></div>${field('Room name',rp+'.name')}${field('Visual description and contents',rp+'.description','textarea')}${field('Purpose in the adventure',rp+'.purpose')}<div class="row">${field('X · tiles from west',rp+'.x','number')}${field('Y · tiles from south',rp+'.y','number')}</div><div class="row">${field('Room width · tiles',rp+'.width','number')}${field('Room height · tiles',rp+'.height','number')}</div><p class="hint">Leave at least two empty tiles between rooms and a one-tile border around the area. Add furnishings in Encounters & items or ask AI to populate this area.</p><details><summary>Resource identity</summary>${field('Room ID',rp+'.id')}<p class="hint">Connections and quest objectives reference this ID.</p></details></div>`:''}<div class="section-head after-card"><div><h3>Room and area connections</h3><p class="hint">Every connection specifies an exit side and a destination.</p></div><button data-action="addConnection">＋ Connection</button></div><div class="connections">${project.connections.map((c,i)=>{if(!a.rooms.some(r=>r.id===c.from_room||r.id===c.to_room))return '';let p='connections.'+i;return `<div class="connection-card"><div class="card-head"><strong>${E(c.name)}</strong><button data-remove="connections:${i}" class="quiet danger">Remove</button></div>${field('Passage name',p+'.name')}<div class="row">${field('From room',p+'.from_room','select',roomOptions())}${field('Exit side',p+'.from_side','select',['north','east','south','west'])}</div><div class="row">${field('To room / area',p+'.to_room','select',roomOptions())}${field('Arrival side',p+'.to_side','select',['north','east','south','west'])}</div><div class="row">${field('Connection type',p+'.kind','select',[['corridor','Physical corridor · same area'],['exit','Area / room transition']])}${field('Open after quest',p+'.requires_quest','select',questOptions())}</div>${field('Travel both ways',p+'.two_way','checkbox')}</div>`;}).join('')||'<div class="empty">Add a connection to another room or area.</div>'}</div><details><summary>Area identity and removal</summary>${field('Area resource ID',ap+'.id')}<button data-action="deleteArea" class="danger">Remove area from draft</button></details></div>${assistant('areas')}</div>`;}
function encounters(){return `<div class="section-head"><div><h2>Fill the adventure with encounters.</h2><p class="muted">Describe combat, ambushes, puzzles, treasure and story moments. Generate them with the AI DM or author each detail.</p></div><button data-action="addEncounter">＋ Encounter</button></div><div class="author-grid"><div>${project.encounters.map((e,i)=>{const p='encounters.'+i;return `<div class="card"><div class="card-head"><span class="badge">${E(e.kind)}</span><button class="quiet danger" data-remove="encounters:${i}">Remove</button></div>${field('Encounter name',p+'.name')}<div class="row">${field('Kind',p+'.kind','select',['combat','ambush','puzzle','treasure','story'])}${field('Room',p+'.room','select',roomOptions())}</div>${field('Describe the encounter you want',p+'.description','textarea')}${field('Available after quest',p+'.after_quest','select',questOptions())}${['combat','ambush'].includes(e.kind)?`<div class="row">${field('Creature',p+'.creature','select',app.authoring_catalog.creatures)}${field('Base number',p+'.count','number')}</div><div class="row">${field('Maximum number',p+'.maximum','number')}${field('Scale count with party size and level',p+'.scale','checkbox')}</div><p class="hint">Combat creatures are placed in the module. Ambushes activate when the party enters the room. Scaling runs inside NWN and needs no AI service.</p>`:`${field('Interaction / puzzle text',p+'.prompt','textarea')}${e.kind==='puzzle'?`<label class="field"><span>Puzzle options · one per line</span><textarea data-lines="${p}.options">${E(e.options.join('\n'))}</textarea></label>${field('Correct option · first option is 0',p+'.answer','number')}${field('Incorrect answer response',p+'.failure','textarea')}`:''}${field('Success / resolution text',p+'.success','textarea')}<div class="row">${field('Gold reward',p+'.gold','number')}${field('XP reward',p+'.xp','number')}</div>`}<details><summary>Resource identity</summary>${field('Encounter ID',p+'.id')}</details></div>`;}).join('')||'<div class="empty">No encounters yet. Add a brief or ask the AI DM to generate them.</div>'}<div class="section-head after-card"><h3>Items and quest objects</h3><button data-action="addItem">＋ Item</button></div>${project.items.map((item,i)=>{let p='items.'+i;return `<div class="card"><div class="card-head"><h3>${E(item.name)}</h3><button data-remove="items:${i}" class="quiet danger">Remove</button></div>${field('Name',p+'.name')}${field('Description',p+'.description','textarea')}<div class="row">${field('Kind',p+'.kind','select',[['quest_token','Quest object'],['healing_potion','Healing potion']])}${field('Quantity',p+'.quantity','number')}</div>${field('Room',p+'.room','select',roomOptions())}${field('Container',p+'.container','select',[['','Own cache'],...project.encounters.filter(e=>e.kind==='treasure').map(e=>[e.id,e.name])])}<details><summary>Resource identity</summary>${field('Item ID',p+'.id')}</details></div>`;}).join('')}<div class="section-head after-card"><h3>Furniture and scenery</h3><button data-action="addFurniture">＋ Furnishing</button></div>${project.furnishings.length?`<div class="entity-grid">${project.furnishings.map((f,i)=>{let p='furnishings.'+i;return `<div class="card compact-fields"><div class="card-head"><strong>${E(f.name)}</strong><button data-remove="furnishings:${i}" class="quiet danger">×</button></div>${field('Name',p+'.name')}${field('Room',p+'.room','select',roomOptions())}${field('Object',p+'.kind','select',app.authoring_catalog.furnishings)}${field('Preferred placement',p+'.placement','select',['north','east','south','west','center'])}${field('Description',p+'.description','textarea')}</div>`;}).join('')}</div>`:'<p class="muted">Ask AI to populate rooms with appropriate furnishings or add them here.</p>'}</div>${assistant('encounters')}</div>`;}
function merchantEditor(n,p){const m=n.merchant;const stockPath=p+'.merchant.stock';const goods=app.authoring_catalog.merchandise;return `<div class="card"><h3>Merchant shop</h3>${field('Enable a finite-stock shop',p+'.merchant.enabled','checkbox')}<p class="hint">Players can browse from the NPC menu or ask through AI chat. Every purchase requires a click in the in-game goods panel. Prices are explicit gold per item.</p>${m.enabled?`${m.stock.map((sku,i)=>{const path=stockPath+'.'+i;return `<div class="branch"><div class="card-head"><strong>${E(goods[sku.item].name)}</strong><button data-remove="${stockPath}:${i}" class="quiet danger">Remove stock</button></div>${field('Stock item',path+'.item','select',Object.entries(goods).map(([k,v])=>[k,v.name]))}<div class="row">${field('Initial quantity',path+'.quantity','number')}${field('Unit price · gold',path+'.price','number')}</div></div>`;}).join('')}<button data-action="addStock" ${m.stock.length>=8?'disabled':''}>＋ Stock item</button><p class="hint">Up to 8 goods and 80 total items. Stock is finite and saved with the game. This first merchant version sells to players; it has no buyback or automatic restocking.</p>${field('Allow haggling',p+'.merchant.haggle_enabled','checkbox')}${m.haggle_enabled?`<div class="row">${field('Success chance · percent',p+'.merchant.haggle_chance','number')}${field('Discount · percent (0–10)',p+'.merchant.discount_percent','number')}</div>${field('Offer duration · active game seconds',p+'.merchant.offer_seconds','number')}<p class="hint">The game rolls once per offer period. Repeated requests reuse that result; discounts do not stack.</p>`:''}`:''}</div>`;}
function recruitEditor(n,p){const c=n.companion;return `<div class="card"><h3>Party companion</h3>${field('Allow this character to be recruited',p+'.companion.recruitable','checkbox')}${c.recruitable?`${field('Protect this essential story companion',p+'.companion.essential','checkbox')}${field('Recruit after quest',p+'.companion.requires_quest','select',questOptions('Available from the beginning'))}${field('Communication',p+'.companion.communication','select',[['speech','Spoken dialogue'],['nonverbal','Nonverbal reactions'],['auto','Automatic from creature type']])}${field('Allow follow, stand-ground and guard orders',p+'.companion.movement','checkbox')}${field('Allow native inventory exchanges',p+'.companion.inventory','checkbox')}${field('Allow inspecting accessible containers',p+'.companion.inspect_containers','checkbox')}${field('Allow owner-directed NPC visits',p+'.companion.social_visits','checkbox')}<p class="hint">Enable companion support in Companions. Recruits use the stock guard combat template and equipment; refine classes and gear in Aurora. Native combat and party controls remain active. A merchant cannot also be a recruit.</p><button data-action="companionSettings">Open companion settings</button>`:''}</div>`;}
function behaviors(){npcIndex=Math.min(npcIndex,Math.max(0,project.npcs.length-1));const n=project.npcs[npcIndex],b=n?.behavior,p='npcs.'+npcIndex+'.behavior';return `<div class="section-head"><div><h2>A world that moves and talks.</h2><p class="muted">Set native patrols and optional public conversations between authored characters.</p></div></div><div class="author-grid"><div><div class="card"><h3>Module behavior switches</h3>${field('Enable native patrols','ambient.patrols','checkbox')}${field('Enable NPC-to-NPC AI conversations','ambient.social','checkbox')}${field('Minimum seconds between exchange attempts','ambient.social_interval','number')}${field('Exchange attempts per active game hour','ambient.social_budget','number')}<p class="hint">Patrols work offline. Social conversations need live AI enabled at export and the local AI Player running. Each exchange uses two short AI requests; failed or interrupted attempts consume budget too.</p></div>${n?`<div class="card"><h3>Character behavior</h3><label class="field"><span>Behavior character</span><select id="npcSelect" aria-label="Behavior character">${project.npcs.map((o,i)=>`<option value="${i}" ${i===npcIndex?'selected':''}>${E(o.name)}</option>`).join('')}</select></label>${field('Enable patrol for this character',p+'.patrol_enabled','checkbox')}${field('Route pattern',p+'.mode','select',[['loop','Loop'],['pingpong','Back and forth']])}${field('Wait at each stop · seconds',p+'.wait_seconds','number')}${field('Run between stops',p+'.run','checkbox')}<h4>Ordered patrol stops</h4>${b.route.map((r,i)=>`<div class="card">${field('Stop '+(i+1),p+'.route.'+i,'select',roomOptions())}<div class="actions"><button data-route-up="${i}" ${i===0?'disabled':''}>Move stop up</button><button data-remove="${p}.route:${i}" class="quiet">Remove stop</button></div></div>`).join('')}<button data-action="addPatrolStop">＋ Patrol stop</button><p class="hint">Use at least two reachable rooms in the character’s starting area, connected by ordinary corridors. Exits do not teleport patrols. Player conversations, combat, possession and recruitment take priority; blocked paths wait before retrying.</p></div><div class="card"><h3>Public NPC conversations</h3>${field('Allow this character to chat with NPCs',p+'.social_enabled','checkbox')}${field('Accept owner-directed companion visits',p+'.accept_visits','checkbox')}<label class="field"><span>Allowed partners · empty allows all opted-in characters</span><select multiple data-multi="${p}.partners">${project.npcs.filter(o=>o.id!==n.id).map(o=>`<option value="${E(o.id)}" ${b.partners.includes(o.id)?'selected':''}>${E(o.name)}</option>`).join('')}</select></label>${field('Public conversation topic',p+'.topic','textarea')}${field('Character cooldown · active seconds',p+'.cooldown','number')}${field('Social communication',p+'.communication','select',[['speech','Spoken dialogue'],['nonverbal','Nonverbal reactions']])}<p class="hint">Both characters must enable social chat and allow each other. They need live AI enabled on their character profiles. Only unowned, idle, nearby, mutually visible actors converse. Each speaker receives their own public knowledge and the pair’s public speech history. Put hidden facts in Secret knowledge, never unconditional knowledge or the public topic.</p></div>`:'<div class="card"><p>Add characters before configuring individual behavior.</p></div>'}<div class="note">Social speech cannot move items, spend gold, change quests or order another actor. Native combat and creature heartbeat scripts remain active. Companions stop ambient patrols/social chat while recruited.</div></div>${assistant('behaviors')}</div>`;}
function companions(){const cfg=project.companions;templateIndex=Math.min(templateIndex,Math.max(0,cfg.templates.length-1));const t=cfg.templates[templateIndex],p='companions.templates.'+templateIndex;const types=[[-1,'Fallback / exact blueprints only'],[0,'Bat'],[1,'Cat / panther'],[2,'Hell hound'],[3,'Imp'],[4,'Fire mephit'],[5,'Ice mephit'],[6,'Pixie'],[7,'Raven'],[8,'Faerie dragon'],[9,'Pseudodragon'],[10,'Eyeball / beholder kin'],[255,'Other native familiar type']];return `<div class="section-head"><div><h2>Companions with their own character.</h2><p class="muted">Create recruitable party members and personalities for the game's actual familiars and summons.</p></div><button data-action="addCompanionTemplate">＋ Custom template</button></div><div class="author-grid"><div><div class="card"><h3>Module companion rules</h3>${field('Enable companion support','companions.enabled','checkbox')}${field('Maximum recruitable companions','companions.party_limit','number')}${field('Enable familiar companions','companions.familiars','checkbox')}${field('Enable summoned companions','companions.summons','checkbox')}<p class="hint">Set recruitment and its quest requirements on individual characters. Familiar and summon profiles attach to existing game creatures; they do not grant spells or summon replacements. Players can restrict these permissions in game.</p></div><div class="card"><h3>Starting personalities</h3><p class="hint">Specific blueprint matches take priority, then familiar type, then one fallback per kind. Edit an existing type to change its starting personality. Add a custom template for a different blueprint.</p>${t?`<div class="select-row"><select id="templateSelect" aria-label="Companion template">${cfg.templates.map((o,i)=>`<option value="${i}" ${i===templateIndex?'selected':''}>${E(o.name)} · ${E(o.kind)}</option>`).join('')}</select><button data-remove="companions.templates:${templateIndex}" class="quiet danger">Remove template</button></div>${field('Template name',p+'.name')}${field('Companion kind',p+'.kind','select',[['familiar','Familiar'],['summon','Summon']])}${t.kind==='familiar'?field('Native familiar type',p+'.familiar_type','select',types):''}<label class="field"><span>Exact creature blueprints · one per line</span><textarea data-lines="${p}.blueprints">${E(t.blueprints.join('\n'))}</textarea></label>${field('Role and relationship',p+'.role')}${field('Personality and preferences',p+'.personality','textarea')}${field('Personal knowledge',p+'.knowledge','textarea')}${field('Boundaries and game guidance',p+'.game_notes','textarea')}${field('Communication style',p+'.communication','select',[['auto','Automatic · animals nonverbal'],['speech','Spoken dialogue'],['nonverbal','Nonverbal reactions']])}${field('Allow live AI conversation',p+'.ai_enabled','checkbox')}${field('Allow AI movement orders',p+'.movement','checkbox')}${field('Allow recoverable satchel inventory',p+'.inventory','checkbox')}${field('Allow inspecting accessible containers',p+'.inspect_containers','checkbox')}${field('Allow owner-directed NPC visits',p+'.social_visits','checkbox')}<details><summary>Template identity</summary>${field('Template ID',p+'.id')}</details>`:'<p class="muted">No familiar or summon templates. Add a template to enable a selected creature.</p>'}</div><div class="note">In game, use !companions for recruitment, follow/stay/guard, conversation preferences and inventory. Familiar history survives resummoning; each summon has a separate identity. Satchels stay in the owner’s inventory for recovery after dismissal. Native game menus, combat and summoning remain active.</div></div>${assistant('companions')}</div>`;}
function cast(){npcIndex=Math.min(npcIndex,Math.max(0,project.npcs.length-1));const n=project.npcs[npcIndex],p='npcs.'+npcIndex;return `<div class="section-head"><div><h2>Characters who belong in the story.</h2><p class="muted">Define their voice, knowledge, secrets and purpose. The AI DM can create the supporting cast from your storyline.</p></div><button data-action="addNPC">＋ Character</button></div><div class="author-grid"><div>${n?`<div class="select-row"><select id="npcSelect" aria-label="Character">${project.npcs.map((n,i)=>`<option value="${i}" ${i===npcIndex?'selected':''}>${E(n.name)}</option>`).join('')}</select><button class="quiet danger" data-action="deleteNPC">Remove</button></div><div class="card"><div class="row">${field('Name',p+'.name')}${field('Role in the story',p+'.role')}</div><div class="row">${field('Room',p+'.room','select',roomOptions())}${field('Native appearance',p+'.appearance','select',app.authoring_catalog.appearances)}</div>${field('Personality and speaking style',p+'.personality','textarea')}${field('Knowledge · facts this character can share',p+'.knowledge','textarea')}${field('Motivation and relationship to the story',p+'.motivation','textarea')}${field('Game-related details · hints, constraints, promises to avoid',p+'.game_notes','textarea')}${field('Secret knowledge',p+'.secret','textarea')}${field('Reveal secret after quest',p+'.reveal_after','select',questOptions('Known from the beginning'))}</div><div class="card"><h3>Authored conversations</h3><p class="hint">These lines are compiled into the module and work for every player without an API key.</p>${field('Opening line',p+'.greeting','textarea')}${n.dialogue.map((d,i)=>`<div class="branch">${field('Player topic',p+'.dialogue.'+i+'.topic')}${field('NPC response',p+'.dialogue.'+i+'.text','textarea')}${field('Unlock after quest',p+'.dialogue.'+i+'.after_quest','select',questOptions())}<button data-remove="npcs.${npcIndex}.dialogue:${i}" class="quiet danger">Remove topic</button></div>`).join('')}<button data-action="addTopic">＋ Dialogue topic</button></div>${merchantEditor(n,p)}${recruitEditor(n,p)}<div class="card"><h3>AI conversation</h3>${field('Allow AI conversation for this character',p+'.ai_enabled','checkbox')}${field('Chat alias',p+'.alias')}<p class="character-note">Profiles guide AI-generated dialogue during authoring. Live freeform conversation can also be included at export, with an optional local player companion. The main story always has authored dialogue.</p><details><summary>Resource identity</summary>${field('NPC ID',p+'.id')}</details></div>`:'<div class="empty">Add your key characters or let the AI DM create a cast for your story.</div>'}</div>${assistant('cast')}</div>`;}
function stepTargets(s){return s.kind==='talk'||s.kind==='choice'?project.npcs.map(n=>[n.id,n.name]):s.kind==='visit'?roomOptions():s.kind==='retrieve'?project.items.map(i=>[i.id,i.name]):project.encounters.filter(e=>s.kind==='defeat'?['combat','ambush'].includes(e.kind):!['combat','ambush'].includes(e.kind)).map(e=>[e.id,e.name]);}
function quests(){questIndex=Math.min(questIndex,Math.max(0,project.quests.length-1));const q=project.quests[questIndex],p='quests.'+questIndex;return `<div class="section-head"><div><h2>Build the path to an ending.</h2><p class="muted">Turn the storyline into executable objectives, character conversations and decisions.</p></div><button data-action="addQuest">＋ Quest</button></div><div class="author-grid"><div>${q?`<div class="select-row"><select id="questSelect" aria-label="Quest">${project.quests.map((q,i)=>`<option value="${i}" ${i===questIndex?'selected':''}>${E(q.name)}${q.optional?' · optional':''}</option>`).join('')}</select><button class="quiet danger" data-action="deleteQuest">Remove</button></div><div class="card">${field('Quest name',p+'.name')}${field('Story purpose',p+'.description','textarea')}${field('Quest starts when talking to',p+'.start_npc','select',npcOptions())}${field('Optional side quest',p+'.optional','checkbox')}<label class="field"><span>Prerequisite quests</span><select data-multi="${p}.requires" multiple size="${Math.max(2,Math.min(5,project.quests.length))}">${project.quests.filter(o=>o.id!==q.id).map(o=>`<option value="${E(o.id)}" ${q.requires.includes(o.id)?'selected':''}>${E(o.name)}</option>`).join('')}</select></label><p class="hint">Hold Ctrl to select multiple prerequisites. All must be completed before this quest starts.</p>${field('Completion text',p+'.completion','textarea')}<div class="row">${field('Gold reward',p+'.gold','number')}${field('XP reward',p+'.xp','number')}</div></div><h3>Objective flow</h3><div class="quest-flow">${q.steps.map((s,i)=>`<div class="quest-node">${i+1}. ${E(s.name)}<small>${E(s.kind)} → ${s.kind==='choice'?s.choices.map(c=>E(c.next||'Complete')).join(' / '):E(s.next||'Complete')}</small></div>`).join('')}</div>${q.steps.map((s,i)=>{let sp=p+'.steps.'+i;let next=[['','Complete this quest'],...q.steps.filter(o=>o.id!==s.id).map(o=>[o.id,o.name])];return `<div class="objective"><div class="card-head"><h3><span class="objective-number">${i+1}</span>${E(s.name)}</h3><button data-remove="quests.${questIndex}.steps:${i}" class="quiet danger">Remove</button></div>${field('Objective name',sp+'.name')}${field('Journal instruction / decision text',sp+'.description','textarea')}<div class="row">${field('Objective type',sp+'.kind','select',['talk','visit','retrieve','defeat','interact','choice'])}${field('Target',sp+'.target','select',[['','Choose a target'],...stepTargets(s)])}</div>${s.kind==='choice'?`${s.choices.map((c,ci)=>`<div class="branch">${field('Player choice',sp+'.choices.'+ci+'.label')}${field('Response / outcome text',sp+'.choices.'+ci+'.text','textarea')}${field('Then',sp+'.choices.'+ci+'.next','select',next)}<button data-remove="quests.${questIndex}.steps.${i}.choices:${ci}" class="quiet danger">Remove choice</button></div>`).join('')}<button data-add-choice="${i}">＋ Branch choice</button>`:`${field('Next objective',sp+'.next','select',next)}${s.kind==='retrieve'?field('Consume this item when the objective completes',sp+'.consume','checkbox'):''}`}<details><summary>Objective identity</summary>${field('Objective ID',sp+'.id')}</details></div>`;}).join('')}<button data-action="addStep">＋ Objective</button><p class="hint">The first objective is the entry point. “Complete this quest” ends the path and grants its reward once. Every main quest must finish before the adventure ending appears.</p><details><summary>Quest identity</summary>${field('Quest ID',p+'.id')}</details>`:'<div class="empty">Ask the AI DM to create quests from your storyline, or add a quest and its objectives here.</div>'}</div>${assistant('quests')}</div>`;}
function reviewHtml(r){if(!r)return '<p class="muted">Check the adventure to verify room reachability, quest targets, branches and prerequisites.</p>';return `<div class="notice ${r.errors.length?'validation-error':''}"><strong>${r.errors.length?r.errors.length+' issue(s) to resolve before building':'Adventure structure is ready to compile'}</strong>${r.errors.length?`<ul class="issues">${r.errors.map(x=>`<li>${E(x)}</li>`).join('')}</ul>`:''}</div>${r.warnings.length?`<details open><summary>${r.warnings.length} authoring note(s)</summary><ul class="issues">${r.warnings.map(x=>`<li>${E(x)}</li>`).join('')}</ul></details>`:''}`;}
function publish(){return `<div class="section-head"><div><h2>A complete module, ready to share.</h2><p class="muted">Compile the world and story into an ordinary NWN module with editable Aurora resources.</p></div><button data-action="build" class="primary">Build adventure</button></div><div class="author-grid review-page"><div><div class="card"><h3>Adventure check</h3><div id="reviewResult">${reviewHtml(report)}</div><button data-action="check">Check again</button></div><div class="card"><h3>Export settings</h3>${field('Module filename','module_name')}${field('Include optional live AI conversations','ai_conversations','checkbox')}<p class="standalone">✓ The main story, authored conversations, quests, puzzles, combat and endings run locally without Studio or an API key.</p><p class="hint">Optional freeform AI conversations require the separate local player companion and the player’s provider key. Authoring-time AI content is already baked into the module.</p><div id="buildResult"></div></div><div class="card"><h3>Shareable builds</h3><div id="buildList">Loading builds…</div></div><div class="card"><h3>Your story at a glance</h3><p class="storyline-preview">${E(project.summary)}</p><h3>Quest paths</h3>${project.quests.map(q=>`<p><strong>${E(q.name)}</strong> ${q.optional?'<span class="pill">Optional</span>':''}<br><span class="hint">${questSummary(q)}</span></p>`).join('')}<h3>World</h3>${project.areas.map(a=>`<p>${E(a.name)} · ${E(app.authoring_catalog.area_types[a.type])} · ${a.width*10} × ${a.height*10} m<br><span class="hint">${a.rooms.map(r=>E(r.name)).join(' · ')}</span></p>`).join('')}</div></div><aside><div class="card accent"><h3>What players receive</h3><ol class="steps"><li>A standard <code>.mod</code> containing the complete adventure.</li><li>Install it in the NWN modules folder.</li><li>Start a new single-player game.</li><li>Play through the story using the native game.</li></ol><p class="hint">The share ZIP also includes instructions, the authoring project, native source resources and validation results.</p></div><div class="card"><h3>Continue in Aurora</h3><p class="muted">Open the exported module in Aurora to refine terrain, object placement, scripts and dialogue.</p><p class="hint">Keep Aurora edits in a separate copy. Rebuilding uses this project’s design, so Aurora changes are not automatically imported back.</p></div><div class="note">Compilation and graph checks run here. Opening in Aurora and testing the adventure in NWN remain the final author playtest.</div></aside></div>`;}
function settings(){return `<div class="card"><h2>Authoring setup</h2><p class="muted">Local module creation. AI generation uses your existing provider key.</p>${Object.entries(app.settings).map(([k,v])=>`<label class="field"><span>${E({model:'AI model',game_root:'NWN installation folder',user_dir:'NWN user folder',compiler:'NWScript compiler'}[k])}</span><input data-setting="${k}" value="${E(v)}"></label>`).join('')}<button data-action="settings" class="primary">Save settings</button><p class="hint">${app.key_available?'Existing OPENAI_API_KEY is available.':'No OPENAI_API_KEY is available to this process.'} Credentials are never included in shared adventures.</p><p class="hint">AI usage this session: ${app.usage.requests} requests · ${app.usage.input_tokens} input tokens · ${app.usage.output_tokens} output tokens.</p><p><a href="/player" target="_blank" rel="noopener">Open optional AI Player companion</a></p></div>`;}
function render(){renderHeader();const views={brief,world,encounters,cast,companions,behaviors,quests,publish,settings};$('#workspace').innerHTML=views[page]();bind();if(page==='publish')builds();}
function set(path,v){const parts=path.split('.');let obj=project;for(const k of parts.slice(0,-1))obj=obj[k];obj[parts.at(-1)]=v;}
function bind(){document.querySelectorAll('[data-field]').forEach(el=>el.addEventListener('input',()=>{const old=value(el.dataset.field);set(el.dataset.field,el.type==='checkbox'?el.checked:typeof old==='number'?Number(el.value):el.value);if(/^quests\.\d+\.steps\.\d+\.kind$/.test(el.dataset.field)){const target=value(el.dataset.field.replace(/\.kind$/,''));target.choices=el.value==='choice'?[{label:'First choice',next:'',text:''},{label:'Second choice',next:'',text:''}]:[];if(el.value==='choice')target.next='';}change();if(el.dataset.field==='title')$('#projectTitle').textContent=project.title;if(/\.merchant\.stock\.\d+\.item$/.test(el.dataset.field)){set(el.dataset.field.replace(/\.item$/,'.price'),app.authoring_catalog.merchandise[el.value].price);render();}if(/\.merchant\.(enabled|haggle_enabled)$/.test(el.dataset.field))render();if(el.dataset.field.endsWith('.companion.recruitable'))render();if(/^companions\.templates\.\d+\.kind$/.test(el.dataset.field))set(el.dataset.field.replace(/\.kind$/,'.familiar_type'),-1);if(el.tagName==='SELECT'&&(/\.kind$/.test(el.dataset.field)||el.dataset.field.endsWith('.type')))render();}));document.querySelectorAll('[data-lines]').forEach(el=>el.oninput=()=>{set(el.dataset.lines,el.value.split('\n').filter(x=>x.trim()));change();});document.querySelectorAll('[data-multi]').forEach(el=>el.onchange=()=>{set(el.dataset.multi,[...el.selectedOptions].map(o=>o.value));change();});
 document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>task(b,()=>action(b.dataset.action)));
 document.querySelectorAll('[data-area]').forEach(b=>b.onclick=()=>{areaIndex=Number(b.dataset.area);roomIndex=0;render();});
 document.querySelectorAll('[data-room],[data-room-map]').forEach(b=>b.onclick=()=>{roomIndex=Number(b.dataset.room??b.dataset.roomMap);render();});
 document.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const [path,index]=b.dataset.remove.split(':');value(path).splice(Number(index),1);change();render();});
 document.querySelectorAll('[data-route-up]').forEach(b=>b.onclick=()=>{const route=project.npcs[npcIndex].behavior.route,i=Number(b.dataset.routeUp);if(i>0){[route[i-1],route[i]]=[route[i],route[i-1]];change();render();}});
 document.querySelectorAll('[data-add-choice]').forEach(b=>b.onclick=()=>{project.quests[questIndex].steps[Number(b.dataset.addChoice)].choices.push({label:'New choice',next:'',text:''});change();render();});
 if($('#templateSelect'))$('#templateSelect').onchange=e=>{templateIndex=Number(e.target.value);render();};
 if($('#npcSelect'))$('#npcSelect').onchange=e=>{npcIndex=Number(e.target.value);render();};if($('#questSelect'))$('#questSelect').onchange=e=>{questIndex=Number(e.target.value);render();};
}
function addNPC(){const ident=id('person_');project.npcs.push({id:ident,name:'New character',alias:ident,role:'Supporting character',room:selectedRoom()?.id||roomOptions()[0]?.[0]||'',appearance:'man',ai_enabled:true,personality:'',knowledge:'',secret:'',reveal_after:'',motivation:'',game_notes:'',greeting:'Greetings, traveler.',dialogue:[],merchant:clone(app.authoring_catalog.merchant_defaults),companion:clone(app.authoring_catalog.npc_companion_defaults),behavior:clone(app.authoring_catalog.behavior_defaults)});npcIndex=project.npcs.length-1;}
async function action(name){
 if(name==='generate'){
  if(generating)throw Error('A proposal is already being generated.');const scope=$('#aiScope').value,instruction=$('#aiDirection').value.trim()||'Use the supplied storyline and design notes to create coherent, playable content for the selected scope.';generating=true;$('#busy').hidden=false;['#projectSelect','#newProject','#importProject'].forEach(s=>$(s).disabled=true);
  try{proposal=await api('/api/author/generate',{project,instruction,scope,area_id:area()?.id||''});showProposal();}finally{generating=false;$('#busy').hidden=true;['#projectSelect','#newProject','#importProject'].forEach(s=>$(s).disabled=false);}
 }
 if(name==='undoAI'&&previousDraft){project=previousDraft;previousDraft=null;change();render();}
 if(name==='addArea'){const ident=id('area_');project.areas.push({id:ident,name:'New area',type:'dungeon',width:14,height:12,room_count:2,description:'',lighting:'cold',rooms:[]});areaIndex=project.areas.length-1;roomIndex=0;change();render();}
 if(name==='arrange'){const r=await api('/api/author/arrange',{project,area_id:area().id});project=r.project;report=r.review;dirty=true;roomIndex=0;render();notify('Room layout generated. Edit the rooms and connect their exits.');}
 if(name==='preview'){report=await api('/api/author/review',{project});render();if(report.errors.length)notify(report.errors.slice(0,5).join('\n'),true);else notify('Corridors routed and adventure connections checked.');}
 if(name==='connectRooms'){autoConnect();change();report=await api('/api/author/review',{project});render();notify('Room corridors added. Review exit sides and the preview.');}
 if(name==='addRoom'){const a=area();const ident=id('room_');a.rooms.push({id:ident,name:'New room',x:1,y:1,width:3,height:3,description:'',purpose:'Exploration'});a.room_count=a.rooms.length;roomIndex=a.rooms.length-1;change();render();notify('Place the new room or regenerate the layout before building.');}
 if(name==='deleteRoom'){area().rooms.splice(roomIndex,1);area().room_count=Math.max(1,area().rooms.length);roomIndex=0;change();render();notify('Room removed. Check connections and content references before building.');}
 if(name==='deleteArea'){project.areas.splice(areaIndex,1);areaIndex=roomIndex=0;change();render();}
 if(name==='addConnection'){const from=selectedRoom()?.id||roomOptions()[0]?.[0]||'',to=roomOptions().find(([id])=>id!==from)?.[0]||'';project.connections.push({id:id('link_'),name:'New passage',from_room:from,to_room:to,from_side:'east',to_side:'west',kind:area()?.rooms.some(r=>r.id===to)?'corridor':'exit',two_way:true,requires_quest:''});change();render();}
 if(name==='addEncounter'){project.encounters.push({id:id('enc_'),name:'New encounter',room:selectedRoom()?.id||roomOptions()[0]?.[0]||'',kind:'combat',description:'',creature:'goblin',count:1,maximum:3,scale:false,after_quest:'',prompt:'',options:[],answer:0,success:'',failure:'',gold:0,xp:0});change();render();}
 if(name==='addItem'){project.items.push({id:id('item_'),name:'Quest object',description:'',room:selectedRoom()?.id||roomOptions()[0]?.[0]||'',container:'',kind:'quest_token',quantity:1});change();render();}
 if(name==='addFurniture'){project.furnishings.push({id:id('prop_'),name:'Supply crate',room:selectedRoom()?.id||roomOptions()[0]?.[0]||'',description:'',kind:'crate',placement:'north'});change();render();}
 if(name==='addNPC'){addNPC();change();render();}
 if(name==='deleteNPC'){project.npcs.splice(npcIndex,1);npcIndex=0;change();render();}
 if(name==='addPatrolStop'){const n=project.npcs[npcIndex];if(n.behavior.route.length>=16)throw Error('Use at most 16 patrol stops.');n.behavior.route.push(n.room);change();render();}
 if(name==='companionSettings'){page='companions';render();}
 if(name==='addCompanionTemplate'){const t=clone(app.authoring_catalog.companion_defaults.templates.find(t=>t.kind==='summon'));t.id=id('cp_');t.name='Custom summoned companion';t.blueprints=[id('creature_')];project.companions.templates.push(t);templateIndex=project.companions.templates.length-1;change();render();}
 if(name==='addStock'){const m=project.npcs[npcIndex].merchant;const item=Object.keys(app.authoring_catalog.merchandise).find(k=>!m.stock.some(s=>s.item===k));if(!item)throw Error('All supported goods have stock lines.');m.stock.push({item,quantity:1,price:app.authoring_catalog.merchandise[item].price});change();render();}
 if(name==='addTopic'){project.npcs[npcIndex].dialogue.push({topic:'Tell me more.',text:'',after_quest:''});change();render();}
 if(name==='addQuest'){project.quests.push({id:id('quest_'),name:'New quest',description:'',start_npc:'',completion:'The quest is complete.',optional:false,requires:[],gold:0,xp:100,steps:[]});questIndex=project.quests.length-1;change();render();}
 if(name==='deleteQuest'){project.quests.splice(questIndex,1);questIndex=0;change();render();}
 if(name==='addStep'){const q=project.quests[questIndex],ident=id('objective_');if(q.steps.length&&q.steps.at(-1).kind!=='choice'&&!q.steps.at(-1).next)q.steps.at(-1).next=ident;q.steps.push({id:ident,name:'New objective',description:'',kind:'talk',target:project.npcs[0]?.id||'',next:'',consume:false,choices:[]});change();render();}
 if(name==='check'){report=await api('/api/author/review',{project});page='publish';render();}
 if(name==='build'){report=await api('/api/author/review',{project});if(report.errors.length){render();throw Error('Resolve the adventure check issues before building.');}$('#reviewResult').innerHTML=reviewHtml(report);const build=await api('/api/build',{project});dirty=false;renderHeader();$('#buildResult').innerHTML=`<div class="build-download"><strong>Native adventure compiled</strong><p>${build.areas} areas · ${build.rooms} rooms · ${build.quests} quests · ${build.compiled_scripts} compiled scripts</p><a href="/download?build=${build.build_id}&kind=zip">Download share / Aurora ZIP</a><a href="/download?build=${build.build_id}&kind=mod">Download .mod</a><button id="installBuild">Install for my playtest</button><p class="hint">Ready for your NWN and Aurora checks.</p></div>`;$('#installBuild').onclick=e=>task(e.target,()=>install(build.build_id));await builds();}
 if(name==='settings'){const settings={};document.querySelectorAll('[data-setting]').forEach(el=>settings[el.dataset.setting]=el.value);await api('/api/settings',settings);app.settings=settings;notify('Authoring settings saved.');}
}
function autoConnect(){const a=area();if(a.rooms.length<2)throw Error('Add or generate at least two rooms.');const groups=new Map(a.rooms.map(r=>[r.id,r.id]));const root=id=>{while(groups.get(id)!==id)id=groups.get(id);return id;};const used=new Set();project.connections.forEach(c=>{used.add(c.from_room+':'+c.from_side);used.add(c.to_room+':'+c.to_side);if(groups.has(c.from_room)&&groups.has(c.to_room))groups.set(root(c.from_room),root(c.to_room));});const pairs=[];for(let i=0;i<a.rooms.length;i++)for(let j=i+1;j<a.rooms.length;j++){const r=a.rooms[i],s=a.rooms[j],dx=s.x+s.width/2-r.x-r.width/2,dy=s.y+s.height/2-r.y-r.height/2;const sides=Math.abs(dx)>=Math.abs(dy)?dx>=0?['east','west']:['west','east']:dy>=0?['north','south']:['south','north'];pairs.push({r,s,sides,d:Math.abs(dx)+Math.abs(dy)});}for(const {r,s,sides} of pairs.sort((a,b)=>a.d-b.d)){if(root(r.id)===root(s.id)||used.has(r.id+':'+sides[0])||used.has(s.id+':'+sides[1]))continue;project.connections.push({id:id('passage_'),name:r.name+' to '+s.name,from_room:r.id,to_room:s.id,from_side:sides[0],to_side:sides[1],kind:'corridor',two_way:true,requires_quest:''});used.add(r.id+':'+sides[0]);used.add(s.id+':'+sides[1]);groups.set(root(r.id),root(s.id));}if(new Set(a.rooms.map(r=>root(r.id))).size>1)notify('Some rooms still need a manually positioned connection.',true);}
async function builds(){const {builds}=await api('/api/builds');if(!$('#buildList'))return;$('#buildList').innerHTML=builds.filter(b=>b.project_id===project.id).reverse().map((b,i)=>`<div class="build"><strong>${E(b.title)}</strong> ${i===0?'<span class="pill">Latest export</span>':''}<p>${E(b.module)} · ${b.areas} areas · ${b.rooms||'?'} rooms · ${b.quests||'?'} quests${b.optional_live_ai?' · optional live AI':''}</p><div class="actions"><a href="/download?build=${b.build_id}&kind=zip">Share / Aurora ZIP</a><a href="/download?build=${b.build_id}&kind=mod">Module</a><a href="/download?build=${b.build_id}&kind=project">Project</a><button data-install="${b.build_id}" class="quiet">Install for playtest</button></div></div>`).join('')||'<p class="muted">No builds yet. Check the adventure, then compile it.</p>';document.querySelectorAll('[data-install]').forEach(b=>b.onclick=()=>task(b,()=>install(b.dataset.install)));}
async function install(build_id){const r=await api('/api/install',{build_id});notify('Installed: '+r.installed+(r.backup?'\nPrevious copy backed up.':''));}
function modal(html,apply=false){$('#modalContent').innerHTML=html;$('#applyProposal').hidden=!apply;$('#modal').showModal();}
function showProposal(){const p=proposal.proposal;modal(`<h2>Review the AI-generated adventure</h2><p class="muted">Nothing has been applied yet. Compare the story, world and quest paths, then apply the proposal to your editable draft.</p><div class="metric-row">${['areas','npcs','encounters','quests','furnishings'].map(k=>`<span>${project[k].length} → ${p[k].length} ${k}</span>`).join('')}</div><h3 class="after-card">${E(p.title)}</h3><p class="storyline-preview">${E(p.summary)}</p><div class="preview-list"><div><h3>World</h3><ul>${p.areas.map(a=>`<li>${E(a.name)} · ${a.width}×${a.height} tiles · ${a.rooms.length} rooms</li>`).join('')}</ul><h3>Characters</h3><ul>${p.npcs.map(n=>`<li>${E(n.name)} — ${E(n.role)}</li>`).join('')}</ul></div><div><h3>Quests</h3><ul>${p.quests.map(q=>`<li>${E(q.name)}<br><small>${questSummary(q)}</small></li>`).join('')}</ul></div></div>${reviewHtml(proposal.review)}<details><summary>Inspect the complete proposal</summary><pre>${E(JSON.stringify(p,null,2))}</pre></details>`,true);}
$('#saveProject').onclick=e=>task(e.target,save);$('#reviewProject').onclick=e=>task(e.target,()=>action('check'));$('#settingsButton').onclick=()=>{page='settings';render();};document.querySelectorAll('nav [data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render();});$('#projectSelect').onchange=async e=>{const ident=e.target.value;await task(null,async()=>{if(dirty)await save();await load(ident);$('#projectSelect').value=ident;});};$('#closeModal').onclick=()=>$('#modal').close();$('#applyProposal').onclick=()=>{previousDraft=clone(project);project=proposal.proposal;dirty=true;report=proposal.review;areaIndex=roomIndex=npcIndex=questIndex=templateIndex=0;proposal=null;$('#modal').close();render();notify('AI proposal applied to the draft. Edit and save when ready.');};
$('#newProject').onclick=()=>{modal('<h2>Create an adventure</h2><p class="muted">Start with your own story and world. No courier quest or fixed characters are required.</p><label class="field"><span>Adventure title</span><input id="newTitle" value="My adventure"></label><label class="field"><span>Project ID · lowercase letters, numbers and underscores</span><input id="newId" placeholder="my_adventure"></label><button id="createProject" class="primary">Create blank adventure</button>');$('#createProject').onclick=e=>task(e.target,async()=>{if(dirty)await save();const r=await api('/api/project/new',{id:$('#newId').value,title:$('#newTitle').value});project=r.project;dirty=false;report=null;page='brief';app.projects=(await api('/api/state')).projects;projectList();$('#modal').close();render();});};$('#importProject').onclick=()=>$('#importFile').click();$('#importFile').onchange=e=>task(null,async()=>{const f=e.target.files[0];if(!f)return;const document=JSON.parse(await f.text());if((document.project||document).schema_version!==2)throw Error('Choose a Module Studio format-2 project. The previous courier template remains available separately.');if(dirty)await save();project=(await api('/api/project/import',{document})).project;dirty=false;report=null;app.projects=(await api('/api/state')).projects;projectList();render();notify('Adventure imported. A previous authoring copy, if present, was backed up.');e.target.value='';});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
(async()=>{try{app=await api('/api/state');projectList();const first=app.projects.find(p=>p.schema_version===2);if(!first)throw Error('No authoring project found');await load(first.id);}catch(e){$('#workspace').textContent='Unable to open Module Studio: '+e.message;}})();
